 assert!(OfflineMapFlow::new(false,c.clone(),vec![b.clone()]).is_err());negatives+=1;
 let mut wrong=b.clone();wrong.mode=5;assert!(OfflineMapFlow::new(true,c.clone(),vec![wrong]).is_err());negatives+=1;
 let mut wrong=b.clone();wrong.plan.namespace=r::ResourceNamespace::Shared;assert!(OfflineMapFlow::new(true,c.clone(),vec![wrong]).is_err());negatives+=1;
 let mut wrong=b.clone();wrong.plan.sectors[0].key.map_id=514;assert!(OfflineMapFlow::new(true,c.clone(),vec![wrong]).is_err());negatives+=1;
 assert!(OfflineMapFlow::new(true,c.clone(),vec![b.clone(),b.clone()]).is_err());negatives+=1;
 let mut flow=OfflineMapFlow::new(true,c.clone(),vec![b.clone()]).unwrap();assert!(flow.begin_entry().is_err());negatives+=1;
 assert!(flow.select(1,526).is_err());negatives+=1;assert!(flow.selected().is_none());flow.select(1,564).unwrap();assert_eq!(flow.selected().unwrap().name,"Battle Ground ");
 let job=flow.begin_entry().unwrap();assert_eq!(flow.page(),Page::Loading);assert!(flow.select(1,564).is_err());negatives+=1;assert!(flow.begin_entry().is_err());negatives+=1;
 assert!(job.load(&AtomicBool::new(true)).is_err());negatives+=1;flow.back().unwrap();
 let stale_job=flow.begin_entry().unwrap();flow.back().unwrap();let current_job=flow.begin_entry().unwrap();
 let stale=stale_job.load(&cancel).unwrap();assert!(flow.complete_entry(stale).is_err());negatives+=1;assert_eq!(flow.page(),Page::Loading);
 let ready=current_job.load(&cancel).unwrap();let mut foreign=OfflineMapFlow::new(true,c.clone(),vec![b.clone()]).unwrap();foreign.select(1,564).unwrap();let _foreign_job=foreign.begin_entry().unwrap();assert!(foreign.complete_entry(ready).is_err());negatives+=1;
 let ready=flow.begin_entry().err();assert!(ready.is_some());negatives+=1;flow.back().unwrap();let ready=flow.begin_entry().unwrap().load(&cancel).unwrap();let first=flow.complete_entry(ready).unwrap();assert_eq!(flow.page(),Page::OfflinePreview);
 let root=p.join("target/r474-offline-map-flow");let images_first=png(&root.join("01-entry-battle-ground.png"),&first);let first_hash=Sha256::digest(first.rgba().unwrap());
 assert!(flow.pan(120,0,&AtomicBool::new(true)).is_err());negatives+=1;assert_eq!(Sha256::digest(first.rgba().unwrap()),first_hash);
 let pan=flow.pan(240,120,&cancel).unwrap();assert!(first.rgba().is_err());negatives+=1;assert_ne!(Sha256::digest(pan.rgba().unwrap()),first_hash);let images_pan=png(&root.join("02-pan-battle-ground.png"),&pan);
 let edge=flow.pan(i32::MAX,i32::MIN,&cancel).unwrap();assert_eq!((edge.camera.x,edge.camera.y),(2272,0));assert!(pan.rgba().is_err());negatives+=1;
 assert!(flow.select(1,564).is_err());negatives+=1;flow.back().unwrap();assert!(edge.rgba().is_err());negatives+=1;assert!(flow.pan(1,1,&cancel).is_err());negatives+=1;assert!(flow.back().is_err());negatives+=1;
 assert_eq!(flow.selected().unwrap().map_id,564);let again=flow.begin_entry().unwrap().load(&cancel).unwrap();let again=flow.complete_entry(again).unwrap();assert_eq!(Sha256::digest(again.rgba().unwrap()),first_hash);assert!(first.rgba().is_err());negatives+=1;let images_again=png(&root.join("03-reentry-battle-ground.png"),&again);drop(flow);assert!(again.rgba().is_err());negatives+=1;
 let result=json!({"state":"ACTUAL_NATIVE_DM564_OFFLINE_MENU_ENTRY_CAMERA_BACK_REENTRY_PASSED","negative_cases":negatives,"catalog_choices":c.choices().len(),"coverage_pairs_cross_checked":40,"pending_pairs":24,"selected_mode":1,"selected_map":564,"source_name":"Battle Ground ","images":[images_first,images_pan,images_again],"history":["menu","select1/564","loading_cancel","menu","old_load_rejected","foreign_load_rejected","entry","pan","edge_clamp","back","reentry","drop"],"default_enabled":false,"renderer_LOADED":false,"GUI":0,"R472_timers_advanced":false,"historical_focused_tests_rerun":0,"complete_mode_acceptance":"16/40 unchanged","scope":"Single real Native sector CPU map preview; camera is Modern inspection UI, no actor/spawn/match/animation/native callback."});
